 private void setupPin(){LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,4),Ui.dp(this,18),0);TextView note=Ui.text(this,"Create a 4-digit PIN. After biometric confirmation, My Vault will open automatically when the fourth digit is entered.",14,Ui.MUTED);note.setPadding(0,0,0,Ui.dp(this,14));box.addView(note);EditText first=pinField("New 4-digit PIN",4),second=pinField("Confirm 4-digit PIN",4);box.addView(first,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));LinearLayout.LayoutParams s=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));s.topMargin=Ui.dp(this,10);box.addView(second,s);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Secure Your Vault").setView(box).setCancelable(false).create();second.addTextChangedListener(new android.text.TextWatcher(){boolean working;public void beforeTextChanged(CharSequence value,int start,int count,int after){}public void onTextChanged(CharSequence value,int start,int before,int count){}public void afterTextChanged(android.text.Editable value){if(working||value.length()!=4)return;String a=first.getText().toString(),b=value.toString();if(!a.matches("\\d{4}")){first.setError("Enter exactly 4 digits");working=true;second.setText("");working=false;return;}if(!a.equals(b)){second.setError("PINs do not match");working=true;second.setText("");working=false;return;}try{working=true;security.set(a);dialog.dismiss();biometric();}catch(Exception error){working=false;Ui.toast(MainActivity.this,"Could Not Secure The PIN");}}});dialog.setOnShowListener(x->{first.requestFocus();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);});dialog.show();}
 private void biometric(){int available=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG);if(available!=BiometricManager.BIOMETRIC_SUCCESS){new AlertDialog.Builder(this).setTitle("Biometric Security Required").setMessage("Please enrol a fingerprint or secure face in your phone settings, then return to unlock this vault.").setCancelable(false).setPositiveButton("Open Settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_BIOMETRIC_ENROLL).putExtra(android.provider.Settings.EXTRA_BIOMETRIC_AUTHENTICATORS_ALLOWED,BiometricManager.Authenticators.BIOMETRIC_STRONG))).setNegativeButton("Close App",(d,w)->finish()).show();return;}BiometricPrompt prompt=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){pinPrompt();}@Override public void onAuthenticationError(int code,CharSequence message){if(code!=BiometricPrompt.ERROR_NEGATIVE_BUTTON)Ui.toast(MainActivity.this,message.toString());}});prompt.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("Unlock My Vault").setSubtitle("Confirm your fingerprint or face").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG).setNegativeButtonText("Close").build());}
