 private void scanMenu(View anchor){PopupWindow popup=new PopupWindow(this);LinearLayout list=Ui.column(this);list.setPadding(Ui.dp(this,6),Ui.dp(this,7),Ui.dp(this,6),Ui.dp(this,7));String[] titles={"Scan Document","Scan Certificate","Scan A Card"};String[] details={"8.5 × 11 Portrait","11 × 8.5 Landscape","Rounded Front And Back"};int[] profiles={SCAN_DOCUMENT,SCAN_CERTIFICATE,SCAN_CARD};for(int i=0;i<titles.length;i++){int profile=profiles[i];LinearLayout option=Ui.column(this);option.setPadding(Ui.dp(this,18),Ui.dp(this,9),Ui.dp(this,18),Ui.dp(this,7));TextView title=Ui.title(this,titles[i],16);option.addView(title);option.addView(Ui.text(this,details[i],12,Ui.MUTED));option.setOnClickListener(v->{popup.dismiss();startScan(profile);});list.addView(option,new LinearLayout.LayoutParams(Ui.dp(this,286),Ui.dp(this,66)));if(i<titles.length-1){View line=new View(this);line.setBackgroundColor(Ui.BORDER);list.addView(line,new LinearLayout.LayoutParams(-1,Ui.dp(this,1)));}}popup.setContentView(list);popup.setWidth(Ui.dp(this,298));popup.setHeight(-2);Ui.polishPopup(this,popup,list,26);popup.showAtLocation(anchor,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,0,Ui.dp(this,96));}
 private void startScan(int profile){scanProfile=profile;if(profile==SCAN_CARD){cardStage=0;scanned.clear();clearNormalizedScans();new AlertDialog.Builder(this).setTitle("Scan The Front Of The Card").setMessage("Place the front of the card inside the scanner. My Vault will capture and shape it with rounded card corners.").setNegativeButton("Cancel",null).setPositiveButton("Scan Front",(d,w)->{cardStage=1;launchScanner(1);}).show();return;}cardStage=0;scanned.clear();clearNormalizedScans();launchScanner(profile==SCAN_QUICK?20:20);}
 private void launchScanner(int pageLimit){GmsDocumentScannerOptions options=new GmsDocumentScannerOptions.Builder().setGalleryImportAllowed(true).setPageLimit(pageLimit).setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG,GmsDocumentScannerOptions.RESULT_FORMAT_PDF).setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build();scanning=true;GmsDocumentScanning.getClient(options).getStartScanIntent(this).addOnSuccessListener(sender->scanLauncher.launch(new IntentSenderRequest.Builder(sender).build())).addOnFailureListener(e->{scanning=false;if(scanProfile==SCAN_CARD)cardStage=0;Ui.toast(this,"Scanner Unavailable: "+e.getMessage());});}
 private void scanResult(ActivityResult activity){scanning=false;if(activity.getResultCode()!=RESULT_OK){if(scanProfile==SCAN_CARD&&cardStage==2)promptForCardBack();else if(scanProfile==SCAN_CARD)cardStage=0;return;}GmsDocumentScanningResult result=GmsDocumentScanningResult.fromActivityResultIntent(activity.getData());ArrayList<Uri> returned=new ArrayList<>();if(result!=null&&result.getPages()!=null)for(GmsDocumentScanningResult.Page page:result.getPages())returned.add(page.getImageUri());if(returned.isEmpty()){Ui.toast(this,"No Pages Were Returned");if(scanProfile==SCAN_CARD&&cardStage==2)promptForCardBack();else cardStage=0;return;}if(scanProfile==SCAN_CARD){processCardSide(returned.get(0));return;}if(scanProfile==SCAN_QUICK){scanned.clear();scanned.addAll(returned);saveDialog();return;}normalizeAndSave(returned);}
 private void normalizeAndSave(ArrayList<Uri> returned){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage(scanProfile==SCAN_CERTIFICATE?"Shaping Landscape Certificate…":"Shaping 8.5 × 11 Document…");wait.show();io.execute(()->{try{ArrayList<Uri> normalized=new ArrayList<>();for(int i=0;i<returned.size();i++)normalized.add(normalize(returned.get(i),scanProfile,i));runOnUiThread(()->{wait.dismiss();scanned.clear();scanned.addAll(normalized);saveDialog();});}catch(Exception error){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Shape The Scan");});}});}
 private void processCardSide(Uri source){int stage=cardStage;ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage(stage==1?"Shaping Card Front…":"Shaping Card Back…");wait.show();io.execute(()->{try{Uri normalized=normalize(source,SCAN_CARD,stage-1);runOnUiThread(()->{wait.dismiss();if(stage==1){scanned.clear();scanned.add(normalized);cardStage=2;promptForCardBack();}else{scanned.add(normalized);cardStage=0;saveDialog();}});}catch(Exception error){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Shape This Side Of The Card");if(stage==2)promptForCardBack();else cardStage=0;});}});}
 private void promptForCardBack(){new AlertDialog.Builder(this).setTitle("Now Scan The Back Of The Card").setMessage("The front is ready. Turn the card over and capture the back to keep both sides together.").setCancelable(false).setNegativeButton("Cancel Card Scan",(d,w)->{cardStage=0;scanned.clear();clearNormalizedScans();}).setPositiveButton("Scan Back",(d,w)->{cardStage=2;launchScanner(1);}).show();}
 private Uri normalize(Uri source,int profile,int index)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream input=getContentResolver().openInputStream(source)){BitmapFactory.decodeStream(input,null,bounds);}int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>2600)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;Bitmap original;try(InputStream input=getContentResolver().openInputStream(source)){original=BitmapFactory.decodeStream(input,null,options);}if(original==null)throw new IOException("Could Not Read Scan");int width,height;if(profile==SCAN_DOCUMENT){width=1600;height=2200;}else if(profile==SCAN_CERTIFICATE){width=2200;height=1600;}else{width=2200;height=1388;}Bitmap output=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(output);canvas.drawColor(profile==SCAN_CARD?Color.TRANSPARENT:Color.WHITE,profile==SCAN_CARD?PorterDuff.Mode.CLEAR:PorterDuff.Mode.SRC);float scale=Math.min((float)width/original.getWidth(),(float)height/original.getHeight());float drawWidth=original.getWidth()*scale,drawHeight=original.getHeight()*scale,left=(width-drawWidth)/2f,top=(height-drawHeight)/2f;Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);if(profile==SCAN_CARD){Path rounded=new Path();rounded.addRoundRect(new RectF(0,0,width,height),115,115,Path.Direction.CW);canvas.save();canvas.clipPath(rounded);canvas.drawColor(Color.WHITE);canvas.drawBitmap(original,null,new RectF(left,top,left+drawWidth,top+drawHeight),paint);canvas.restore();}else canvas.drawBitmap(original,null,new RectF(left,top,left+drawWidth,top+drawHeight),paint);original.recycle();File dir=new File(getCacheDir(),"normalized_scans");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Could Not Create Scan Cache");File file=new File(dir,"scan-"+System.currentTimeMillis()+"-"+index+(profile==SCAN_CARD?".png":".jpg"));try(OutputStream out=new FileOutputStream(file)){output.compress(profile==SCAN_CARD?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,95,out);}output.recycle();return Uri.fromFile(file);}
 private void clearNormalizedScans(){File dir=new File(getCacheDir(),"normalized_scans");File[] files=dir.listFiles();if(files!=null)for(File file:files)file.delete();}
 private void saveDialog(){LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,5),Ui.dp(this,18),0);EditText title=Ui.field(this,scanProfile==SCAN_CARD?"Card or ID name":"Document name",false);box.addView(title,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));Spinner category=new Spinner(this);String[] values=scanProfile==SCAN_CARD?new String[]{"Bank Cards","ID / Permit"}:new String[]{"ID / Permit","Certificates","Bank Cards","Documents"};category.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));if(scanProfile==SCAN_CERTIFICATE)category.setSelection(1);else if(scanProfile==SCAN_DOCUMENT||scanProfile==SCAN_QUICK)category.setSelection(values.length-1);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));cp.topMargin=Ui.dp(this,10);box.addView(category,cp);String summary=scanProfile==SCAN_CARD?"Front and back are ready to encrypt together":scanned.size()+" cleaned page"+(scanned.size()==1?"":"s")+" ready to encrypt";TextView pages=Ui.text(this,summary,13,Ui.TEAL);pages.setPadding(2,Ui.dp(this,12),0,0);box.addView(pages);AlertDialog d=new AlertDialog.Builder(this).setTitle(scanProfile==SCAN_CARD?"Save Card Or ID":"Save To My Vault").setView(box).setNegativeButton("Discard",(x,w)->{scanned.clear();clearNormalizedScans();scanProfile=SCAN_QUICK;}).setPositiveButton("Encrypt & Save",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isEmpty()){title.setError(scanProfile==SCAN_CARD?"Give this card or ID a name":"Give this document a name");return;}d.getButton(-1).setEnabled(false);io.execute(()->{try{repo.add(name,values[category.getSelectedItemPosition()],new ArrayList<>(scanned));runOnUiThread(()->{d.dismiss();scanned.clear();clearNormalizedScans();scanProfile=SCAN_QUICK;load();Ui.toast(this,"Document Encrypted And Saved");});}catch(Exception e){runOnUiThread(()->{d.getButton(-1).setEnabled(true);Ui.toast(this,"Could Not Save The Scan");});}});}));d.show();title.requestFocus();d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void cloudMenu(){String[] options={"Appearance & Theme","Backup Account","Vault Health","Search My Vault","Create Recovery Code","Back Up Encrypted Vault","Verify Cloud Backup","Restore On A Replacement Phone","Open PC Portal","How PC Access Works","Check For Updates"};new AlertDialog.Builder(this).setTitle("My Vault Settings").setItems(options,(d,i)->{if(i==0)themeDialog();else if(i==1)authenticateCloud(3);else if(i==2)startActivity(new Intent(this,VaultHealthActivity.class));else if(i==3)startActivity(new Intent(this,VaultSearchActivity.class));else if(i==4)showRecoveryCode();else if(i==5)authenticateCloud(0);else if(i==6)authenticateCloud(2);else if(i==7)authenticateCloud(1);else if(i==8)startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://badimps.github.io/secure-document-wallet/")));else if(i==9)new AlertDialog.Builder(this).setTitle("Two-Step PC Access").setMessage("The private web portal sends a one-time code to your email, then asks for your private recovery code. Files remain encrypted while stored online.").setPositiveButton("OK",null).show();else UpdateManager.check(this,true);}).show();}
 private void themeDialog(){String[] names={"Aegis Blue  ·  Professional Default","Emerald Institutional  ·  Calm And Trusted","Ocean Blue  ·  Crisp And Professional","Warm Sand  ·  Editorial And Refined","Obsidian Reserve  ·  Premium Dark","Lumen Glass  ·  Frosted And Modern"};new AlertDialog.Builder(this).setTitle("Choose Your Theme").setSingleChoiceItems(names,ThemeManager.selected(this),(dialog,which)->{ThemeManager.set(this,which);dialog.dismiss();recreate();}).setNegativeButton("Cancel",null).show();}
 private void authenticateCloud(int action){EditText email=Ui.field(this,"Email address",false);email.setText(cloud.accountEmail());email.setSelection(email.length());email.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(email,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Create Or Connect Backup Account").setMessage("Enter your email. A free one-time code signs you in, and creates your encrypted-backup account if this is your first time.").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Send Code",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String address=email.getText().toString().trim();if(!android.util.Patterns.EMAIL_ADDRESS.matcher(address).matches()){email.setError("Enter a valid email");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{cloud.sendCode(address);runOnUiThread(()->{dialog.dismiss();codeDialog(address,action);});}catch(Exception e){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);Ui.toast(this,e.getMessage());});}});}));dialog.show();}
 private void codeDialog(String email,int action){EditText code=Ui.field(this,"Code Or Verification Link",false);code.setGravity(Gravity.CENTER);FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(code,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Verify Your Email").setMessage("Enter the one-time code sent to "+email+". The email link opens the secure PC portal; you can also paste that link here.").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Verify",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String token=code.getText().toString().trim();if(token.length()<6){code.setError("Enter the code or secure link");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{cloud.verify(email,token);runOnUiThread(()->{dialog.dismiss();if(action==1)recoveryRestoreDialog();else if(action==3)Ui.toast(this,"Backup account connected");else runCloud(action);});}catch(Exception e){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);code.setError(e.getMessage());});}});}));dialog.show();}
 private void runCloud(int action){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage(action==0?"Encrypting and backing up…":"Verifying cloud backup…");wait.show();io.execute(()->{try{int count=action==0?cloud.backup(security.vaultSalt()):cloud.verifyBackup();runOnUiThread(()->{wait.dismiss();Ui.toast(this,(action==0?"Cloud backup complete: ":"Cloud backup verified: ")+count+" encrypted files");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,e.getMessage());});}});}
 private void recoveryRestoreDialog(){EditText code=Ui.field(this,"Recovery code",false);code.setGravity(Gravity.CENTER);FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(code,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Restore On This Phone").setMessage("Enter the recovery code saved when the backup was created. For safety, restore requires an empty vault.").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Restore",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String value=code.getText().toString().trim();if(value.length()<24){code.setError("Enter the complete recovery code");return;}dialog.getButton(-1).setEnabled(false);ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Restoring and authenticating encrypted files…");wait.show();io.execute(()->{try{int count=cloud.restoreWithRecovery(value);runOnUiThread(()->{wait.dismiss();dialog.dismiss();home();Ui.toast(this,"Cloud restore complete: "+count+" encrypted files");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();dialog.getButton(-1).setEnabled(true);code.setError(e.getMessage());});}});}));dialog.show();}
 private void showRecoveryCode(){try{String code=RecoveryKit.create(this);TextView value=Ui.text(this,code,19,Ui.NAVY);value.setTextIsSelectable(true);value.setGravity(Gravity.CENTER);value.setPadding(Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18));new AlertDialog.Builder(this).setTitle("Save Your Recovery Code").setMessage("Write this down and keep it away from your phone. Creating a replacement code makes the previous recovery code invalid after your next backup.").setView(value).setCancelable(false).setPositiveButton("I Saved It",null).show();}catch(Exception e){Ui.toast(this,"Could Not Create A Recovery Code");}}
